from taf.collectors.journal.factory import JournalCollectorFactorySelector
from taf.collectors.core import core
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class journal(core):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def create_journal_collector(self,
                                 name,
                                 options=None,
                                 journal_path=None,
                                 target_file_name=None,
                                 executor=None,
                                 sudo_password=None):
        """
                Create Journal Collector from given configuration

                :param str name: name of collector
                :param str options: (optional) "-o json" is its default value.
                :param str journal_path: (Optional) Path of journal path executable, default value is "journal"
                :param str target_file_name: (optional) file name part of the path under which the journal file is
                                            stored locally during collect_collectors and the suffix for
                                            will depend on the value, that the tester provides for "options".
                                            ex: target_file_name = journal.log or target_file_name = journal.json
                :param dict executor: (Optional) setup info host, user, password,in dict format
                :param str sudo_password: (Optional) password for sudo, if sudo_password is omitted:
                        sudo is configured in a way, that no password is requested for the used user.

                :return: JournalCollector : created object of JournalCollector

.. code-block:: Robot

            Robot Testcase
            *** Settings ***
            Library    taf.collectors.journal    WITH NAME    journal
            Library    taf.collectors.core    WITH NAME    core

            *** Test Cases ***
            Get JournalLogs from Remote machine
                ${executor_oam_vm}=  Create Dictionary
                ...  host=10.43.204.207
                ...  user=robot
                ...  password=rastre1
                journal.create_journal_collector
                ...     name=journal
                ...     options=-o json
                ...     executor=${executor_oam_vm}
                core.setup_collectors    names=journal
                core.start_collectors    names=journal
                sleep    10s
                core.stop_collectors    names=journal
                core.collect_collectors    names=journal
                core.teardown_collectors    names=journal


            Get JournalLogs from Local machine
                journal.create_journal_collector
                ...    name=journal
                ...    options=-o json
                ...    sudo_password=ute
                core.setup_collectors    names=journal
                core.start_collectors    names=journal
                sleep    10s
                core.stop_collectors    names=journal
                core.collect_collectors    names=journal
                core.teardown_collectors    names=journal

            """
        configuration = {"name": name}
        if executor is not None:
            configuration["executor"] = executor
        if options is not None:
            configuration["options"] = options
        if journal_path is not None:
            configuration["journal_path"] = journal_path
        if target_file_name is not None:
            configuration["target_file_name"] = target_file_name
        if sudo_password is not None:
            configuration["sudo_password"] = sudo_password
        logger.info("Creating Journal Collector with alias name " + name)
        journal = JournalCollectorFactorySelector().create(configuration=configuration, existing_arguments={})
        logger.info("Journal Collector created successfully")
        self.set_alias(name, journal)
